CREATE TABLE driver_vehicles(user_id uuid PRIMARY KEY REFERENCES users(id),plate text NOT NULL,description text NOT NULL,city text NOT NULL,expires_on date NOT NULL,available boolean NOT NULL DEFAULT false);
CREATE TABLE rides(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id),pet_id uuid NOT NULL REFERENCES pets(id),driver_id uuid REFERENCES users(id),city text NOT NULL,origin_label text NOT NULL,destination_label text NOT NULL,origin_lat numeric(9,6) NOT NULL,origin_lng numeric(9,6) NOT NULL,destination_lat numeric(9,6) NOT NULL,destination_lng numeric(9,6) NOT NULL,fare_minor bigint NOT NULL CHECK(fare_minor>0),driver_share bigint NOT NULL CHECK(driver_share>0 AND driver_share<=fare_minor),status text NOT NULL DEFAULT 'requested' CHECK(status IN ('requested','accepted','driver_en_route','arrived','in_transit','completed','cancelled','disputed')),idempotency_key uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(user_id,idempotency_key));
CREATE UNIQUE INDEX one_active_ride_per_driver ON rides(driver_id) WHERE status IN ('accepted','driver_en_route','arrived','in_transit');
CREATE TABLE ride_locations(ride_id uuid PRIMARY KEY REFERENCES rides(id),driver_id uuid NOT NULL REFERENCES users(id),lat numeric(9,6) NOT NULL,lng numeric(9,6) NOT NULL,shared boolean NOT NULL,expires_at timestamptz NOT NULL);
CREATE TABLE ride_incidents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),ride_id uuid NOT NULL REFERENCES rides(id),actor_id uuid NOT NULL REFERENCES users(id),description text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE notifications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id),event_id uuid NOT NULL REFERENCES outbox_messages(event_id),title text NOT NULL,read_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(user_id,event_id));
ALTER TABLE outbox_messages ADD COLUMN attempts integer NOT NULL DEFAULT 0;
ALTER TABLE outbox_messages ADD COLUMN available_at timestamptz NOT NULL DEFAULT now();
ALTER TABLE outbox_messages ADD COLUMN failed_at timestamptz;
ALTER TABLE outbox_messages ADD COLUMN last_error text;
CREATE TABLE notification_preferences(user_id uuid PRIMARY KEY REFERENCES users(id),in_app boolean NOT NULL DEFAULT true,quiet_start integer CHECK(quiet_start BETWEEN 0 AND 23),quiet_end integer CHECK(quiet_end BETWEEN 0 AND 23));
CREATE TABLE cms_pages(slug text PRIMARY KEY,title text NOT NULL,body text NOT NULL,published boolean NOT NULL DEFAULT false,version integer NOT NULL DEFAULT 1,updated_by uuid NOT NULL REFERENCES users(id),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE platform_finance_grants(user_id uuid PRIMARY KEY REFERENCES users(id),scopes text[] NOT NULL CHECK(scopes<@ARRAY['maker','checker']::text[]),revoked_at timestamptz);
CREATE TABLE sandbox_payouts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),kind text NOT NULL CHECK(kind IN ('clinic','driver','fund')),party_id uuid NOT NULL,amount_minor bigint NOT NULL CHECK(amount_minor>0),created_by uuid NOT NULL REFERENCES users(id),reviewed_by uuid REFERENCES users(id),status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','paid','reconciled')),statement_reference text UNIQUE,created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE outbox_messages ADD COLUMN queued_at timestamptz;
